import{_ as a,o as s,c as r,a3 as o}from"./chunks/framework.qCVWde4n.js";const g=JSON.parse('{"title":"出问题了怎么查","description":"","frontmatter":{},"headers":[],"relativePath":"use/troubleshooting.md","filePath":"use/troubleshooting.md","lastUpdated":null}'),n={name:"use/troubleshooting.md"};function e(l,t,i,d,p,h){return s(),r("div",null,[...t[0]||(t[0]=[o(`<h1 id="出问题了怎么查" tabindex="-1">出问题了怎么查 <a class="header-anchor" href="#出问题了怎么查" aria-label="Permalink to &quot;出问题了怎么查&quot;">​</a></h1><p><strong>系统化的排查路径。</strong> 遇到问题按本篇的顺序走，绝大多数都能自己定位。</p><h2 id="第一步-先判断问题类型" tabindex="-1">第一步：先判断问题类型 <a class="header-anchor" href="#第一步-先判断问题类型" aria-label="Permalink to &quot;第一步：先判断问题类型&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>去哪一步</th></tr></thead><tbody><tr><td>游戏<strong>打不开</strong> / 秒退</td><td><a href="#一启动问题游戏打不开">一、启动问题</a></td></tr><tr><td>游戏能进，但<strong>战斗中崩溃</strong></td><td><a href="#二战斗中崩溃">二、战斗中崩溃</a></td></tr><tr><td>数值<strong>不对</strong> / 和预期不一样</td><td><a href="#三数值不对">三、数值不对</a></td></tr><tr><td>面板<strong>打不开</strong> / 点不动</td><td><a href="#四面板打不开">四面板打不开</a></td></tr><tr><td>Mod <strong>装了没效果</strong></td><td><a href="#五mod-没生效">五mod-没生效</a></td></tr><tr><td><strong>存档</strong>读不出 / 丢了</td><td><a href="#六存档问题">六存档问题</a></td></tr><tr><td>其他 / 说不清</td><td><a href="#通用排查流程">直接看通用流程</a></td></tr></tbody></table><hr><h2 id="通用排查流程" tabindex="-1">通用排查流程 <a class="header-anchor" href="#通用排查流程" aria-label="Permalink to &quot;通用排查流程&quot;">​</a></h2><p>无论什么问题，先按这个顺序收集信息：</p><div class="language-mermaid vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart TD</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    A[&quot;遇到问题&quot;] --&gt; B[&quot;状态页&lt;br/&gt;看偏离清单&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    B --&gt; C[&quot;日志页&lt;br/&gt;筛「错误」&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    C --&gt; D{&quot;有错误？&quot;}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    D --&gt;|有| E[&quot;按错误内容处理&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    D --&gt;|没有| F[&quot;筛「告警」&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    F --&gt; G{&quot;有告警？&quot;}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    G --&gt;|有| H[&quot;多半是冲突&lt;br/&gt;见 Mod 冲突排查&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    G --&gt;|没有| I[&quot;复制全部日志&lt;br/&gt;发给作者&quot;]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><div class="tip custom-block"><p class="custom-block-title">三个必看的地方</p><ol><li><strong>状态页</strong> —— 现在是什么状况（有没有参数偏离、倍速多少）</li><li><strong>日志页「错误」筛选</strong> —— 有没有真出错</li><li><strong>日志页「告警」筛选</strong> —— 有没有 Mod 冲突</li></ol><p><strong>这三步能覆盖 80% 的问题定位。</strong></p></div><hr><h2 id="一、启动问题-游戏打不开" tabindex="-1">一、启动问题（游戏打不开） <a class="header-anchor" href="#一、启动问题-游戏打不开" aria-label="Permalink to &quot;一、启动问题（游戏打不开）&quot;">​</a></h2><h3 id="症状" tabindex="-1">症状 <a class="header-anchor" href="#症状" aria-label="Permalink to &quot;症状&quot;">​</a></h3><ul><li>点图标没反应</li><li>闪一下就退出</li><li>卡在启动画面</li></ul><h3 id="排查顺序" tabindex="-1">排查顺序 <a class="header-anchor" href="#排查顺序" aria-label="Permalink to &quot;排查顺序&quot;">​</a></h3><p><strong>① 是安装问题还是框架问题？</strong></p><p>装回纯汉化版（<code>final_full_cn.apk</code>）试试：</p><table tabindex="0"><thead><tr><th>结果</th><th>结论</th></tr></thead><tbody><tr><td>纯汉化版也打不开</td><td><strong>不是框架问题</strong> —— 是设备/安装问题，看 <a href="/AtlanticFleetSite/docs/deploy/android">安装问题</a></td></tr><tr><td>纯汉化版能开，Mod 版不能</td><td><strong>可能和 Mod 配置有关</strong>，继续往下</td></tr></tbody></table><p><strong>② 是不是某个 Mod 的配置有错？</strong></p><p>用文件管理器把 <code>mods/</code> 下的<strong>所有子文件夹临时改名</strong>（前面加个下划线），框架就不加载它们了。</p><p>能进游戏后，再一个一个改回来，定位是哪个。</p><p><strong>③ 内存够吗？</strong></p><p>启动就崩，很可能是<strong>内存不足</strong>。游戏本体对内存有要求（建议 8 GB）。</p><p>试试：关机重启 → 清后台 → 再进。</p><div class="warning custom-block"><p class="custom-block-title">关于内存</p><p>框架本身占用极小。如果启动就崩，更可能是<strong>游戏本体的内存需求</strong>。</p><p>这一点框架帮不上忙 —— 设备内存不够就是不够。</p></div><hr><h2 id="二、战斗中崩溃" tabindex="-1">二、战斗中崩溃 <a class="header-anchor" href="#二、战斗中崩溃" aria-label="Permalink to &quot;二、战斗中崩溃&quot;">​</a></h2><h3 id="症状-1" tabindex="-1">症状 <a class="header-anchor" href="#症状-1" aria-label="Permalink to &quot;症状&quot;">​</a></h3><p>能进游戏、能操作，但<strong>一进战斗就闪退</strong>。</p><h3 id="排查顺序-1" tabindex="-1">排查顺序 <a class="header-anchor" href="#排查顺序-1" aria-label="Permalink to &quot;排查顺序&quot;">​</a></h3><p><strong>① 看日志页有没有错误</strong></p><p>进游戏后立刻去日志页 → 筛「错误」。</p><p>常见的错误类型：</p><table tabindex="0"><thead><tr><th>错误内容</th><th>可能原因</th></tr></thead><tbody><tr><td>模型加载相关</td><td>自制模型包有问题</td></tr><tr><td>舰船数据相关</td><td>自定义舰船的字段有问题</td></tr><tr><td>引擎异常</td><td>看具体内容</td></tr></tbody></table><p><strong>② 检查自制模型</strong></p><p>如果你用了自制模型，<strong>先把相关 Mod 禁掉试试</strong>。</p><p>模型问题最容易导致战斗崩溃（因为战斗开始时要实例化所有舰船模型）。</p><div class="tip custom-block"><p class="custom-block-title">模型的三档兜底</p><p>理论上框架有兜底（自制 → 内置 → 不可见），<strong>不应该崩</strong>。</p><p>如果崩了，说明遇到了兜底没覆盖的情况 —— 这时候日志里的内容很关键，请反馈。</p></div><p><strong>③ 检查自定义舰船</strong></p><p>舰船的字段如果有极端值（比如武器数量填了负数），可能引发问题。</p><p>试试禁掉自定义舰船的 Mod。</p><hr><h2 id="三、数值不对" tabindex="-1">三、数值不对 <a class="header-anchor" href="#三、数值不对" aria-label="Permalink to &quot;三、数值不对&quot;">​</a></h2><h3 id="症状-2" tabindex="-1">症状 <a class="header-anchor" href="#症状-2" aria-label="Permalink to &quot;症状&quot;">​</a></h3><ul><li>「我明明设了 2.0，但感觉只有 1.2」</li><li>「数值好像被改过但我没改」</li></ul><h3 id="排查顺序-2" tabindex="-1">排查顺序 <a class="header-anchor" href="#排查顺序-2" aria-label="Permalink to &quot;排查顺序&quot;">​</a></h3><p><strong>① 看状态页的偏离清单</strong></p><p>如果清单是<strong>空的</strong>，说明<strong>没有任何参数偏离原版</strong>，问题可能不在参数。</p><p><strong>② 看是不是被别的 Mod 覆盖了</strong></p><p>去 <a href="/AtlanticFleetSite/docs/use/conflicts">Mod 冲突排查</a>。</p><p><strong>③ 检查硬边界</strong></p><p>如果你<strong>手写 mod.json</strong> 且值超出了硬边界，会被<strong>静默截断</strong>。</p><p>对照 <a href="/AtlanticFleetSite/docs/features/matrix">功能接入总表</a> 的硬边界列。</p><div class="warning custom-block"><p class="custom-block-title">这个最容易困惑</p><p><code>gun.damageMul: 99</code>，硬边界是 <code>5</code> → <strong>实际生效 <code>5</code></strong>，而且<strong>不报错</strong>。</p><p>所以「我写了 99 但感觉没效果」是正常的 —— 它被截到 5 了。</p></div><p><strong>④ 确认重开游戏了</strong></p><p>参数在启动时读取。改了不重开，还是旧值。</p><hr><h2 id="四、面板打不开" tabindex="-1">四、面板打不开 <a class="header-anchor" href="#四、面板打不开" aria-label="Permalink to &quot;四、面板打不开&quot;">​</a></h2><h3 id="症状-3" tabindex="-1">症状 <a class="header-anchor" href="#症状-3" aria-label="Permalink to &quot;症状&quot;">​</a></h3><p>悬浮窗看不见，或者点了没反应。</p><h3 id="立刻试这一招" tabindex="-1">立刻试这一招 <a class="header-anchor" href="#立刻试这一招" aria-label="Permalink to &quot;立刻试这一招&quot;">​</a></h3><div class="tip custom-block"><p class="custom-block-title">三根手指同时按屏幕</p><p>这是<strong>强制唤起</strong>手势，走完全独立的输入通道，不依赖点击事件。</p><p><strong>大多数「点不动」的问题，三指同按都能解决。</strong></p></div><h3 id="如果三指也不行" tabindex="-1">如果三指也不行 <a class="header-anchor" href="#如果三指也不行" aria-label="Permalink to &quot;如果三指也不行&quot;">​</a></h3><p><strong>① 悬浮窗是不是被挡了</strong></p><p>可能有别的东西盖住了它。试试：</p><ul><li>退出到主菜单再进来</li><li>换个界面（比如从战斗界面回到大地图）</li></ul><p><strong>② 是不是位置跑到屏幕外了</strong></p><p>拖动姿势太极端时可能拖到屏幕边缘外。</p><p><strong>解决</strong>：删掉 <code>AFMOD_settings.json</code>（位置设置会重置）。</p><p><strong>③ 是不是游戏本身的问题</strong></p><p>如果游戏其他界面也点不动，那不是框架的问题。</p><hr><h2 id="五、mod-没生效" tabindex="-1">五、Mod 没生效 <a class="header-anchor" href="#五、mod-没生效" aria-label="Permalink to &quot;五、Mod 没生效&quot;">​</a></h2><h3 id="症状-4" tabindex="-1">症状 <a class="header-anchor" href="#症状-4" aria-label="Permalink to &quot;症状&quot;">​</a></h3><p>装了 Mod，但感觉没变化。</p><h3 id="排查顺序-3" tabindex="-1">排查顺序 <a class="header-anchor" href="#排查顺序-3" aria-label="Permalink to &quot;排查顺序&quot;">​</a></h3><p><strong>① 重开游戏了吗</strong></p><div class="warning custom-block"><p class="custom-block-title">这是最常见的原因</p><p>Mod <strong>只在启动时读取一次</strong>。</p><p>装好 / 改好之后，必须<strong>完全退出游戏</strong>（从后台任务划掉），再重新打开。</p><p>按 Home 键返回桌面<strong>不算退出</strong>。</p></div><p><strong>② 装的位置对吗</strong></p><p>正确：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mods/</span></span>
<span class="line"><span>└── 某个文件夹/</span></span>
<span class="line"><span>    └── mod.json</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>错误：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mods/</span></span>
<span class="line"><span>└── mod.json          ← 直接在根目录，读不到</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p><strong>③ 用状态页确认</strong></p><p>去状态页看偏离清单：</p><table tabindex="0"><thead><tr><th>结果</th><th>结论</th></tr></thead><tbody><tr><td>Mod 的参数<strong>出现在清单里</strong></td><td><strong>生效了</strong> —— 可能只是效果不明显</td></tr><tr><td>清单里<strong>没有</strong></td><td>没加载成功</td></tr></tbody></table><p><strong>④ 看日志页</strong></p><p>日志会记录：</p><ul><li>扫到了哪些 Mod</li><li>每个 Mod 解析是否成功</li><li>参数被改成了什么</li></ul><p>如果日志里<strong>根本没提到这个 Mod</strong>，说明文件没被扫到（位置或文件名问题）。</p><hr><h2 id="六、存档问题" tabindex="-1">六、存档问题 <a class="header-anchor" href="#六、存档问题" aria-label="Permalink to &quot;六、存档问题&quot;">​</a></h2><h3 id="症状-5" tabindex="-1">症状 <a class="header-anchor" href="#症状-5" aria-label="Permalink to &quot;症状&quot;">​</a></h3><ul><li>存档读不出</li><li>进度丢了</li><li>改了存档但没生效</li></ul><h3 id="排查顺序-4" tabindex="-1">排查顺序 <a class="header-anchor" href="#排查顺序-4" aria-label="Permalink to &quot;排查顺序&quot;">​</a></h3><p><strong>① 改了之后点「保存到存档」了吗</strong></p><p>存档页的修改<strong>必须点保存</strong>才写盘。不点保存，退出就白改了。</p><p><strong>② 存档文件还在吗</strong></p><p>位置：<code>Android/data/&lt;游戏包名&gt;/files/rncampaignInfo.dat</code></p><ul><li>文件在 → 存档没丢</li><li>文件不在 → 检查是不是重装过应用（卸载会清数据）</li></ul><p><strong>③ 有备份吗</strong></p><p>如果你按 <a href="/AtlanticFleetSite/docs/deploy/android">安装文档</a> 的建议备份过，直接恢复。</p><h3 id="一个安心的说明" tabindex="-1">一个安心的说明 <a class="header-anchor" href="#一个安心的说明" aria-label="Permalink to &quot;一个安心的说明&quot;">​</a></h3><div class="tip custom-block"><p class="custom-block-title">框架改存档走的是游戏官方接口</p><p>框架<strong>不直接改二进制文件</strong>，而是改运行时的值 + 调用游戏自己的保存方法。</p><p>所以理论上<strong>不会写出游戏读不了的存档</strong>。</p><p>如果真遇到读不出，更可能是：改动前的存档就已经有问题，或者重装导致的数据丢失。</p></div><hr><h2 id="收集信息发给作者" tabindex="-1">收集信息发给作者 <a class="header-anchor" href="#收集信息发给作者" aria-label="Permalink to &quot;收集信息发给作者&quot;">​</a></h2><p>如果自己排查不出来，按这个清单收集：</p><h3 id="必提供" tabindex="-1">必提供 <a class="header-anchor" href="#必提供" aria-label="Permalink to &quot;必提供&quot;">​</a></h3><ol><li><strong>日志</strong>：日志页 →「复制全部日志」→ 粘贴 （或直接把 <code>AFMOD_log.txt</code> 文件发过来）</li><li><strong>现象描述</strong>：什么情况下出问题、什么表现</li></ol><h3 id="尽量提供" tabindex="-1">尽量提供 <a class="header-anchor" href="#尽量提供" aria-label="Permalink to &quot;尽量提供&quot;">​</a></h3><ol start="3"><li><strong>装了哪些 Mod</strong>：Mod 页截图</li><li><strong>改了哪些参数</strong>：状态页的偏离清单</li><li><strong>设备信息</strong>：手机型号、系统版本、内存大小</li></ol><h3 id="加上这些会快很多" tabindex="-1">加上这些会快很多 <a class="header-anchor" href="#加上这些会快很多" aria-label="Permalink to &quot;加上这些会快很多&quot;">​</a></h3><ol start="6"><li><strong>能不能稳定复现</strong>：还是偶发</li><li><strong>换一个没装 Mod 的存档试过吗</strong></li><li><strong>是装框架之前就有，还是装之后才有</strong></li></ol><div class="tip custom-block"><p class="custom-block-title">日志为什么这么重要</p><p>因为日志是<strong>唯一能还原现场的东西</strong>。</p><p>没有日志，作者只能靠猜。有日志，很多问题一眼就能看出来。</p><p>框架特意把日志<strong>落盘写入文件</strong>，就是为了这个 —— 游戏关了日志还在。</p></div><hr><h2 id="一张速查表" tabindex="-1">一张速查表 <a class="header-anchor" href="#一张速查表" aria-label="Permalink to &quot;一张速查表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>第一步</th></tr></thead><tbody><tr><td>游戏打不开</td><td>装回纯汉化版对比 → 排除是不是框架问题</td></tr><tr><td>进战斗闪退</td><td>禁用自制模型相关 Mod</td></tr><tr><td>数值不对劲</td><td>状态页看偏离 → 查 Mod 冲突 → 查硬边界</td></tr><tr><td>面板点不动</td><td><strong>三指同按屏幕</strong></td></tr><tr><td>Mod 没效果</td><td><strong>重开游戏</strong> → 检查目录结构 → 看日志</td></tr><tr><td>存档读不出</td><td>检查文件在不在 → 恢复备份</td></tr></tbody></table><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><ul><li>Mod 冲突专篇 → <a href="/AtlanticFleetSite/docs/use/conflicts">Mod 冲突排查</a></li><li>日志怎么用 → <a href="/AtlanticFleetSite/docs/use/log-page">日志页：自查问题</a></li><li>状态怎么看 → <a href="/AtlanticFleetSite/docs/use/status-page">状态页：看现场</a></li><li>安装问题 → <a href="/AtlanticFleetSite/docs/deploy/android">安卓手机安装</a></li></ul>`,118)])])}const u=a(n,[["render",e]]);export{g as __pageData,u as default};
